    rorVerdictNegative: '期待値がマイナス：この数字では破産はリスクではなく、長期的には数学的必然です。リスクを調整する前に、優位性のあるシステムが必要です。',
    rorVerdictHigh: 'システムに優位性はありますが、1トレードのリスクが高すぎます——破産確率は依然深刻です。1トレードの%を下げて、確率が急落するのを見てください。',
    rorVerdictOk: '堅実な組み合わせ：正の優位性と管理されたリスク。ただしシミュレーションは完璧な規律——ストップが常に守られること——を前提としています。',
