    goldenRule2Name: '1トレードのリスクは最大1〜2%',
    goldenRule2Desc: '各損失を資金に対して小さく保つ。そうすればどの一回の取引も連敗も、あなたを退場させられない。',
    goldenRule3Name: 'ストップを不利な方向へ動かさない',
    goldenRule3Desc: '利益を守るために動かすのはよいが、含み損に『余裕』を与えるために動かしてはならない。ストップを広げることこそ、小さな損が巨大になる原因。',
    goldenRule4Name: '含み損を難平しない',
    goldenRule4Desc: '含み損のポジションに買い増すことは、間違っているまさにその時にリスクを増やす行為。買い増すのは勝ちポジションであって、負けポジションではない。',
    goldenRule5Name: '損は切り、利は伸ばす',
    goldenRule5Desc: '他のすべてを支える原則。多くの人は恐怖と強欲から逆をやる。良いリワード/リスク比は低い勝率を許してくれる。',
    goldenRule6Name: '計画なしで取引しない',
    goldenRule6Desc: 'エントリー・ストップ・目標・サイズをエントリー『前』に決める。なぜ入るのか書けないなら、入るな。',
    goldenRule7Name: 'リベンジやFOMOで取引しない',
    goldenRule7Desc: '口座を吹き飛ばす最速の2つの方法。怒りや取り残される恐怖で入るなら、始める前にすでに負けている。',
    goldenRule8Name: '耐えられないレバレッジを使わない',
    goldenRule8Desc: 'レバレッジは腕を上げてくれない。結果（良し悪し）を早めるだけ。普通の一本の足で強制決済されるなら、サイズが大きすぎる。',
    riskRewardTitle: 'リスク/リワード比率',
    riskRewardDesc: '常に潜在的な利益がリスクの少なくとも2倍である取引を探してください。1:2以上の比率が不可欠です。',
    diversificationTitle: '分散投資',
    diversificationDesc: 'すべての卵を一つのかごに入れないでください。異なる資産と戦略に分散して全体的なリスクを減らします。',
    
    // Dow Theory - JAPANESE
    dowTheoryTitle: 'ダウ理論',
    dowTheoryIntro: 'ダウ理論は現代のテクニカル分析の基礎であり、チャールズ・ダウによって19世紀末に開発されました。市場の動きを理解するための基本原則を確立しています。',
    
    dowPrinciple1Title: '1. 市場はすべてを織り込む',
    dowPrinciple1Desc: '市場価格は利用可能なすべての情報を反映しています：ファンダメンタル、政治、心理、期待。需要と供給に影響を与える可能性のある要因はすでに価格に組み込まれています。',
    
    dowPrinciple2Title: '2. 市場には3つのトレンドがある',
    dowPrinciple2Desc: '主要トレンド：1年から数年続く主要な市場の動き。二次トレンド：主要トレンドに対する修正で、数週間または数ヶ月続く。小トレンド：数日または数週間続く短期的な変動。',
    
    dowPrinciple3Title: '3. 主要トレンドには3つの段階がある',
    dowPrinciple3Desc: '蓄積段階：情報を持つ投資家がセンチメントがネガティブな時に購入する。一般参加段階：一般大衆がトレンドを認識し参加する。分配段階：情報を持つ投資家が楽観論がピークの時に売却する。',
    
    dowPrinciple4Title: '4. 指数は互いに確認し合う必要がある',
    dowPrinciple4Desc: 'トレンドシグナルが有効であるためには、異なる市場指数が同じ方向に動く必要があります。指数間の乖離は、トレンドが弱いか偽物である可能性を示唆します。',
    
    dowPrinciple5Title: '5. 出来高はトレンドを確認する必要がある',
    dowPrinciple5Desc: '出来高は主要トレンドの方向に増加する必要があります。上昇トレンドでは、上昇時に出来高が増加し、修正時に減少します。下降トレンドでは逆が起こります。',
    
    dowPrinciple6Title: '6. トレンドは明確なシグナルがその反転を示すまで持続する',
    dowPrinciple6Desc: 'トレンドは変化したという明確な証拠があるまで有効です。小さな変動はトレンドの変化を示すのに十分ではありません。明確な反転パターンが必要です。',
    
    dowApplicationTitle: '実践的な応用',
    dowApplicationDesc: 'ダウ理論を適用するには：1）高値と安値を観察して主要トレンドを特定する。2）出来高の確認を待つ。3）明確なパターンがある場合のみ反転シグナルを探す。4）主要トレンドの方向に取引する。5）二次修正をエントリーポイントとして使用する。',
    
    dowLimitationsTitle: '制限事項',
    dowLimitationsDesc: 'ダウ理論はトレンドの期間や規模を予測しません。シグナルは動きがすでに始まった後に遅れて到着する可能性があります。非常に短期的な取引には適していません。流動性が高く時価総額が大きい市場で最も効果的です。',
    
    // Trading Psychology - JAPANESE
