    sessNyDesc: '最も変動が大きく、重要な経済指標が集中',
    sessOverlapName: 'ロンドン/NY重複時間',
    sessOverlapHours: '13:00 - 17:00 UTC',
    sessOverlapDesc: '最も流動性とボラティリティが高い時間帯',
    marketTypesIntro: 'どの市場にも独自の取引時間・流動性・ボラティリティ・変動要因があります。何を取引しているか、そして各市場がどう動くかを理解することが最初の優位性です。同じ戦略でも、ある市場では勝ち、別の市場では負けることがあります。',
    marketParticipantsIntro: '価格は、規模・時間軸・動機がまったく異なるプレーヤー同士の綱引きの結果です。誰が、なぜ相場を動かしているかを知れば、注文フローに逆らうのではなく読み解けるようになります。',
    sessionsIntro: '市場はアジア太平洋・欧州・米州の三つの地域が交代しながら24時間動いています。ボラティリティ・スプレッド・最適な銘柄は時間帯で変わり、セッションの重複時間帯に出来高の大半が集中します。',
    mktBondsName: '債券 / 債券市場',
    mktBondsDesc: '政府や企業が発行する債務。規模では世界最大の市場で、国債利回り（米10年債など）はあらゆる資産価格の基準となる『リスクフリー』金利を決めます。金利とは逆に動きます。',
    mktBondsVolume: '約140兆ドル残高',
    mktOptionsName: 'オプション',
    mktOptionsDesc: '満期前に決められた価格で原資産を買う（コール）／売る（プット）『権利』（義務ではない）を与える契約。ヘッジ・収益獲得・レバレッジと限定リスクでの投機に使われます。価格はボラティリティと時間に依存します。',
    mktOptionsVolume: '約500億ドル/日（米国）',
    mktCfdsName: 'CFD（差金決済）',
    mktCfdsDesc: '差金決済取引：資産を保有せずに価格変動だけを取引でき、レバレッジをかけて買い・売り両方が可能。欧州で株価指数・FX・商品に人気ですが、レバレッジは損失を拡大し、コスト（スプレッド/オーバーナイト金利）がかさみます。',
    mktCfdsVolume: 'ブローカーによる',
    partBanksName: '投資銀行・商業銀行',
    partBanksDesc: '市場のインフラ。マーケットメイク、巨額の顧客注文の執行、自己勘定デスクの運営を行い、FXを支配します。そのリサーチと注文フローが短期の方向性を左右します。',
    partHedgeFundsName: 'ヘッジファンド',
    partHedgeFundsDesc: '規制の緩いファンドで、積極的で柔軟な戦略（ロング・ショート、マクロ、裁定、クオンツ）で絶対収益を狙います。相場を素早く動かすことがあり、個人トレードの反対側にいる『スマートマネー』であることが多いです。',
    partFundsName: '年金・投資信託',
    partFundsDesc: '最大級の長期資金の担い手。年金や貯蓄のためにゆっくり大口で投資します。そのリバランスの資金フローや指数採用の判断は、数週間〜数か月かけてセクター全体を動かします。',
    partHftName: 'HFT・アルゴリズム',
    partHftDesc: '高頻度取引（HFT）業者は超高速アルゴリズムでマイクロ秒単位の取引を行い、現在の流動性の多くを供給し、数百万の注文でわずかなスプレッドを積み重ねます。日中の出来高を支配します。',
    partBrokersName: 'ブローカー・ディーラー',
    partBrokersDesc: '市場へのアクセスを提供する仲介者。注文を取引所に流す業者（ECN/STP）もあれば、反対側を取る業者（マーケットメイカー/ディーラー）もあります。注文の回し方が約定とコストに影響します。',
    partCorporatesName: '事業会社・ヘッジャー',
    partCorporatesDesc: '実体のある企業（航空会社・輸出企業・鉱山会社）が、投機ではなく燃料・通貨・原材料といった実際のエクスポージャーをヘッジするために先物やFXを使います。その安定した方向性のないフローが商品・FX市場の土台です。',
    sessSydneyName: 'シドニー（太平洋）',
    sessSydneyHours: '22:00–07:00 UTC',
    sessSydneyDesc: '取引週の始まりを告げるセッション。流動性が薄くボラティリティは低め。主にAUD・NZD・JPYのペア。レンジ戦略に向き、値動きが不安定になりやすいためブレイクアウトにはリスクがあります。',
    sessOverlap2Name: 'シドニー–東京の重複',
    sessOverlap2Hours: '00:00–07:00 UTC',
    sessOverlap2Desc: 'アジア太平洋が本格稼働：AUD・NZD・JPYやアジア株価指数が最も活発になる時間帯。地域指標や中国に左右される中程度のボラティリティ。',
    techTitle: 'テクニカル分析',
