    basicsFaqLong2Q: 'ロングをいつ開くべきですか？',
    basicsFaqLong2A: '分析が価格上昇の可能性を示しているとき：レジスタンスのブレイク後、強いサポートで、強気 momentum が確認されたとき、またはチャートに強気パターンシグナルが現れたとき。',
    basicsFaqLong3Q: 'leverage なしのロングで投資額以上を失うことはありますか？',
