    basicsTpTitle: 'Take Profit (TP) — 利益目標',
    basicsTpBadge: '必須',
    basicsTpDesc: 'Take Profit は価格があらかじめ設定した利益目標に達したときに自動的にポジションをクローズする注文です。欲を抑えるツールです：分析が示す地点で利益を確定することを強制します。',
    basicsTpBen1Title: '欲を排除',
